import{_ as r,l as i,o as a,c as s,v as o,p as n,x as l,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"全双工语音 Moshi","description":"","frontmatter":{"title":"全双工语音 Moshi","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/full-duplex-speech.md","filePath":"llm/full-duplex-speech.md","lastUpdated":1789023840000}'),c={name:"llm/full-duplex-speech.md"};function m(u,e,_,f,T,E){const t=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="全双工语音-moshi" tabindex="-1">全双工语音 Moshi <a class="header-anchor" href="#全双工语音-moshi" aria-label="Permalink to &quot;全双工语音 Moshi&quot;">​</a></h1><div class="epigraph"><p>对话不是「你说完我再说」。同时听、插话、边听边组织下一句，才是全双工。</p><footer>—— Défossez 等 Moshi: a speech-text foundation model for real-time dialogue</footer></div><p><a href="/llm/valle-tts">上一课</a>是提示到整句合成。缺口是时间上重叠的听与说：用户可能打断，模型也可能在用户说话时出声或等待。Moshi 用语音–文本基础模型加全双工编解码。后课端到端对话默认双工栈已经存在，再问要不要把文本当必经中间件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>半双工流水线：ASR → LLM → TTS，延迟叠三跳，而且强制轮次。用户插话时 TTS 还在播，系统不知道该停。全双工要求：输入音频流与输出音频流同时活着，内部状态按帧更新。Moshi 用 Mimi 等低延迟 codec，RQ-Transformer 多流（用户声、自己的声、文本「内心独白」）对齐到同一时间格。</p><p>Inner Monologue 把文本当作与语音并行的潜流，而不是先写完整句再念。</p><p><span class="marginnote">帧长（如 80 ms）决定可插话粒度。比它短的停顿无法被当作轮次边界。这与视频时间 ID 必须对齐绝对时间是同一类协议。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流式 codec → 多流 Transformer → 流式解码。训练数据要含重叠说话、打断、停顿，不能只用干净朗读。评测：端到端延迟、打断后是否停、内容是否仍连贯；不要用离线 TTS MOS 代替双工。</p>',9)),(a(),n(p,null,{default:l(()=>[h(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E7%94%A8%E6%88%B7%E9%9F%B3%E9%A2%91%E6%B5%81%22%5D%20--%3E%20MOS%5B%22%E5%A4%9A%E6%B5%81%20Transformer%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%E6%BD%9C%E6%B5%81%22%5D%20--%3E%20MOS%0A%20%20MOS%20--%3E%20OUT%5B%22%E6%A8%A1%E5%9E%8B%E9%9F%B3%E9%A2%91%E6%B5%81%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多流让「正在听的声学」与「正在说的声学」分键值，避免自己的回声被当成用户。文本潜流提供可训练的语言规划，使语音不全是声学续写。没有这条潜流，模型容易声学流畅、语义空转。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Moshi 仍是一条特定栈。下一课把「语音进语音出、文本可选」收成对话系统问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全双工是同时听说与打断，不是更快的 TTS。</li><li>多流与短帧 codec 是时间协议。</li><li>文本潜流用来规划内容。</li><li>出处：Défossez 等 Moshi。</li></ul>',6))])}const M=r(c,[["render",m]]);export{A as __pageData,M as default};
